def transform(grid):
    from collections import Counter
    H = len(grid); W = len(grid[0])
    allc = Counter(x for row in grid for x in row)
    bg = allc.most_common(1)[0][0]
    # connected components of non-bg cells (4-conn)
    seen = [[False]*W for _ in range(H)]
    comps = []  # (color, r0, r1, c0, c1)
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] != bg:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
                rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
                color = Counter(grid[p[0]][p[1]] for p in cells).most_common(1)[0][0]
                comps.append((color, min(rs), max(rs), min(cs), max(cs), len(cells)))
    out = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == bg:
                continue
            neigh = []
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr==0 and dc==0: continue
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < H and 0 <= nc < W:
                        neigh.append(grid[nr][nc])
            if not all(n != v for n in neigh):
                continue
            # find smallest component whose bbox contains (r,c), excluding single-cell comps at (r,c)
            best = None
            for color, r0, r1, c0, c1, size in comps:
                if r0 <= r <= r1 and c0 <= c <= c1 and not (size == 1 and grid[r][c] == color and r0 == r and c0 == c):
                    if best is None or size < best[1]:
                        best = (color, size)
            out[r][c] = best[0] if best else bg
    return out
